changeSet.sql:
-- Dọn sạch mock/seed products và variants nếu còn tồn tại trên các môi trường
DELETE FROM public.order_items WHERE product_id IN (
    SELECT id FROM public.products WHERE id::text LIKE '22222222-2222-2222-2222-%'
    OR id::text LIKE '33333333-3333-3333-3333-%'
    OR id::text LIKE '60b00000-%'
    OR sku IN ('SDB-PRO-06', 'SDB-NEW-05')
);

DELETE FROM public.inventory_movements WHERE variant_id IN (
    SELECT id FROM public.product_variants WHERE id::text LIKE '33333333-3333-3333-3333-%'
    OR id::text LIKE '60b00000-%'
);

DELETE FROM public.product_variants WHERE id::text LIKE '33333333-3333-3333-3333-%'
    OR id::text LIKE '60b00000-%'
    OR product_id::text LIKE '22222222-2222-2222-2222-%';

DELETE FROM public.products WHERE id::text LIKE '22222222-2222-2222-2222-%'
    OR id::text LIKE '33333333-3333-3333-3333-%'
    OR id::text LIKE '60b00000-%'
    OR sku IN ('SDB-PRO-06', 'SDB-NEW-05');
